resource "ztc_traffic_forwarding_rule" "this" {
  name                = substr(var.name,0,31)                         #Only uses first 32character - limitation by ZIA API
  description         = join("---",[var.name,var.description])        # Consistent with SIPA firewall_rule module
  order               = 1
  state               = "ENABLED"
  type                = "EC_RDR"
  forward_method      = "DIRECT"
  rule_label               = var.rule_label_sipa  # not supported by ZTC Terraform Provider

  nw_services {
    id = [data.ztc_network_services.this.id]
  }

  dest_ip_groups {
    id = [data.ztc_network_dest_groups.this.id]
  }


  lifecycle {
    ignore_changes = [ order, rank ]
  }

}
